<?php require __DIR__.'/_init.php';require_login();$errors=[];$cats=['IT Support','Library Services','Accommodation','Academic Support','General Administration'];if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$cat=$_POST['category']??'';$title=trim($_POST['title']??'');$desc=trim($_POST['description']??'');$priority=$_POST['priority']??'normal';if(!in_array($cat,$cats,true))$errors[]='Choose a listed category.';if(mb_strlen($title)<4||mb_strlen($title)>120)$errors[]='Title must be 4–120 characters.';if(mb_strlen($desc)<10||mb_strlen($desc)>5000)$errors[]='Description must be 10–5000 characters.';if(!in_array($priority,['low','normal','high'],true))$errors[]='Choose a valid priority.';if(!$errors){$days=match($priority){'high'=>2,'low'=>8,default=>5};$db=db();$db->beginTransaction();$tracking='CF-'.strtoupper(bin2hex(random_bytes(5)));$s=$db->prepare('INSERT INTO service_requests(tracking_id,user_id,category,title,description,priority,expected_days) VALUES(?,?,?,?,?,?,?)');$s->execute([$tracking,$_SESSION['user']['id'],$cat,$title,$desc,$priority,$days]);$id=(int)$db->lastInsertId();$h=$db->prepare("INSERT INTO request_status_history(request_id,changed_by,new_status,note) VALUES(?,?,'submitted','Request received')");$h->execute([$id,$_SESSION['user']['id']]);$db->commit();flash('Request submitted. Tracking ID: '.$tracking);header('Location: /requests.php');exit;}}page_start('New request');?><section class="form-wrap wide"><div class="eyebrow">CAMPUS SUPPORT</div><h1>What can we help with?</h1><?php foreach($errors as $x)echo '<p class="error">'.e($x).'</p>';?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Category<select name="category" required><option value="">Choose a category</option><?php foreach($cats as $c)echo '<option>'.e($c).'</option>';?></select></label><label>Request title<input name="title" maxlength="120" required></label><label>What happened?<textarea name="description" rows="6" required></textarea></label><label>Priority<select name="priority"><option value="normal">Normal</option><option value="high">High</option><option value="low">Low</option></select></label><p class="hint">Transparent estimate: high priority 2 days, normal 5 days, low 8 days.</p><button class="button">Submit request →</button></form></section><?php page_end();?>
